  6	/** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
  7	public final class EmailSender {
  8	
  9	    private final SentMessages sentMessages;
 10	    private final List<EmailRule> rules;
 11	
 12	    public EmailSender(SentMessages sentMessages) {
 13	        this(sentMessages, buildRules());
 14	    }
 15	
 16	    EmailSender(SentMessages sentMessages, List<EmailRule> rules) {
 17	        this.sentMessages = sentMessages;
 18	        this.rules = rules;
 19	    }
 20	
 21	    public Message send(String to, String subject, String body) {
 22	        OutgoingMessage message = new OutgoingMessage(to, subject, body);
 23	        RuleResult result = new RuleResult();
 24	
 25	        for (EmailRule rule : rules) {
 26	            rule.apply(message, result);
 27	        }
 28	
 29	        Message sent = sentMessages.add("EMAIL", message.to(), message.subject(), message.body(), message.status());
 30	
 31	        for (OutgoingMessage additional : result.additionalMessages()) {
 32	            sentMessages.add("EMAIL", additional.to(), additional.subject(), additional.body(), additional.status());
 33	        }
 34	
 35	        return sent;
 36	    }
