 38	    private static List<EmailRule> buildRules() {
 39	        List<EmailRule> rules = new ArrayList<>();
 40	        rules.add(new EmailValidationRule());
 41	
 42	        boolean testMode = "true".equals(System.getenv("HOTEL_TEST_MODE"));
 43	        if (testMode) {
 44	            rules.add(new TestModeRule());
 45	        } else {
 46	            rules.add(new ArchiveCopyRule());
 47	        }
 48	
 49	        return rules;
 50	    }
 51	}
