 54	final class EmailValidationRule implements EmailRule {
 55	
 56	    @Override
 57	    public void apply(OutgoingMessage message, RuleResult result) {
 58	        if (!isValid(message.to())) {
 59	            message.block();
 60	        }
 61	    }
 62	
 63	    private boolean isValid(String email) {
 64	        int atIndex = email.indexOf('@');
 65	        if (atIndex <= 0) {
 66	            return false;
 67	        }
 68	        if (atIndex != email.lastIndexOf('@')) {
 69	            return false;
 70	        }
 71	        String domain = email.substring(atIndex + 1);
 72	        return domain.contains(".");
 73	    }
 74	}
